      const link=row.querySelector('.ver_correlatividades');
      if(!link||link.dataset.completo==='true'){resolve(true);return;}
      const finish=ok=>{clearTimeout(deadline);observer.disconnect();resolve(ok);};
      const observer=new MutationObserver(()=>{if(link.dataset.completo==='true')finish(true);});
