    const extra=el('div','extras');for(const entrance of [false,true]){const list=selected.filter(c=>!c.year&&c.entrance===entrance);if(!list.length)continue;const sec=el('section');sec.append(el('h2',null,entrance?'Ingreso':'Seminarios y otras actividades'),el('p','muted',entrance?'Se muestran aparte y no suman al avance de la carrera.':'Sin año asignado en el plan de Guaraní.'));const grid=el('div','extra-grid');list.forEach(c=>grid.append(card(c)));sec.append(grid);extra.append(sec);}if(extra.childElementCount)container.append(extra);
