    lastFocus=trigger;dialog.replaceChildren();const avg=average(courses);const title=el('h2',null,'Promedio del plan');title.id='unla-course-title';dialog.append(title,el('p',null,avg.value===null?'Todavía no hay aprobaciones con nota numérica.':`${avg.value.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})} sobre 10`));
    const list=el('ul','average-list');for(const c of avg.graded)list.append(el('li',null,`${displayName(c.name)}: ${c.value.toLocaleString('es-AR')}`));if(avg.count)dialog.append(list);
    dialog.append(el('p','detail-note','Promedio simple de las notas numéricas de actividades aprobadas o promocionadas del plan, incluidos los seminarios. Excluye módulos de ingreso y actividades sin nota. No equivale al promedio oficial del historial académico, que puede incluir otros intentos.'));
